1	//! Evidence that a function renders, so a typed PascalCase function is a component and not a helper that happens to
2	//! take an object. A typed first parameter alone admits `FormatName = (u: User) => string`, `debounce((q: Row) => …)`
3	//! and selectors, so every rule that infers a component from a function asks this first.
4	//!
5	//! What the function returns decides, not what appears anywhere in its body: JSX built in a nested callback or never
6	//! returned is not evidence.
7	
8	use oxc_ast::ast::*;
9	use oxc_ast_visit::{Visit, walk};
10	use oxc_syntax::scope::ScopeFlags;
11	use rustc_hash::FxHashSet;
12	
13	/// Why a function was judged not to render. Carried into the skip diagnostic.
14	pub(super) type NoRender = &'static str;
15	
16	/// Names whose type, as a return annotation, means the function renders.
17	const ELEMENT_TYPE_NAMES: &[&str] = &["Element", "ReactElement", "ReactNode", "ReactPortal", "JSX"];
18	
19	/// Callees that produce an element, by name. Preact's `h` is not here: so short a name proves nothing until it is
20	/// known to be imported from Preact (`Scope::is_preact_h`).
21	const ELEMENT_FACTORIES: &[&str] = &["createElement", "cloneElement", "jsx", "jsxs", "jsxDEV", "createPortal"];
22	
23	/// Whether a callee name names an element factory, given the receiver it was called on (`Preact` in `Preact.h(…)`).
24	/// `h` counts only as Preact's own binding, bare or on Preact's namespace: `codec.h(…)` and a local helper called `h`
25	/// are not factories.
26	pub(super) fn is_element_factory_name(name: &str, receiver: Option<&str>, scope: &dyn Scope) -> bool {
27	    if name == "h" {
28	        return scope.is_preact_h(receiver);
29	    }
30	    ELEMENT_FACTORIES.contains(&name)
31	}
32	
33	/// Whether a call's callee is an element factory: see [`is_element_factory_name`].
34	pub(super) fn is_element_factory_callee(callee: &Expression<'_>, scope: &dyn Scope) -> bool {
35	    match callee {
36	        Expression::Identifier(id) => is_element_factory_name(id.name.as_str(), None, scope),
37	        Expression::StaticMemberExpression(m) => {
38	            let receiver = match super::component::named(&m.object) {
39	                Some(Expression::Identifier(object)) => Some(object.name.as_str()),
40	                _ => Some(""),
41	            };
42	            is_element_factory_name(m.property.name.as_str(), receiver, scope)
43	        }
44	        _ => false,
45	    }
46	}
47	
48	/// Whether a type name, as written in this file, can be React's or the global `JSX` namespace's. Given the name's
49	/// leftmost segment (`React` for `React.ReactNode`), so an element-like name imported from another module does not
50	/// count.
51	pub(super) type ReactBinding<'f> = &'f dyn Scope;
52	
53	/// What the file around a function says about the names it uses.
54	pub(super) trait Scope {
55	    /// Whether a type name can be React's: see [`ReactBinding`].
56	    fn may_be_react(&self, name: &str) -> bool;
57	    /// Whether a call to this name returns an element: a same-file function declared to return one.
58	    fn is_element_helper(&self, name: &str) -> bool;
59	    /// Whether the call is React's `memo(…)` or `forwardRef(…)`, by where its callee was imported from.
60	    fn is_react_wrapper(&self, call: &CallExpression<'_>) -> bool;
61	    /// Whether `h` called bare (`receiver` is `None`) or on `receiver` (`Preact.h`) is Preact's, by where it was
62	    /// imported from.
63	    fn is_preact_h(&self, receiver: Option<&str>) -> bool;
64	}
65	
66	fn leftmost_and_rightmost<'n>(name: &'n TSTypeName<'_>) -> Option<(&'n str, &'n str)> {
67	    match name {
68	        TSTypeName::IdentifierReference(id) => Some((id.name.as_str(), id.name.as_str())),
69	        TSTypeName::QualifiedName(q) => {
70	            let mut left = &q.left;
71	            while let TSTypeName::QualifiedName(inner) = left {
72	                left = &inner.left;
73	            }
74	            match left {
75	                TSTypeName::IdentifierReference(id) => Some((id.name.as_str(), q.right.name.as_str())),
76	                _ => None,
77	            }
78	        }
79	        _ => None,
80	    }
81	}
82	
83	/// Whether a return type annotation names a renderable result bound to React: `JSX.Element`, `ReactNode`,
84	/// `ReactElement`, a union containing one, or `Promise` of one (async server components).
85	pub(super) fn type_renders(ty: &TSType<'_>, react: ReactBinding<'_>) -> bool {
86	    match ty {
87	        TSType::TSTypeReference(r) => {
88	            let Some((left, right)) = leftmost_and_rightmost(&r.type_name) else { return false };
89	            if right == "Promise" {
90	                return r
91	                    .type_arguments
92	                    .as_ref()
93	                    .and_then(|a| a.params.first())
94	                    .is_some_and(|t| type_renders(t, react));
95	            }
96	            ELEMENT_TYPE_NAMES.contains(&right) && react.may_be_react(left)
97	        }
98	        TSType::TSUnionType(u) => u.types.iter().any(|t| type_renders(t, react)),
99	        TSType::TSParenthesizedType(p) => type_renders(&p.type_annotation, react),
100	        _ => false,
101	    }
102	}
103	
104	fn callee_name<'n>(callee: &'n Expression<'_>) -> Option<&'n str> {
105	    match callee {
106	        Expression::Identifier(id) => Some(id.name.as_str()),
107	        Expression::StaticMemberExpression(m) => Some(m.property.name.as_str()),
108	        _ => None,
109	    }
110	}
111	
112	fn is_hook_name(name: &str) -> bool {
113	    name.strip_prefix("use").is_some_and(|rest| rest.starts_with(|c: char| c.is_ascii_uppercase()))
114	}
115	
116	fn is_children(expr: &Expression<'_>) -> bool {
117	    match expr {
118	        Expression::Identifier(id) => id.name == "children",
119	        Expression::StaticMemberExpression(m) => m.property.name == "children",
120	        _ => false,
121	    }
122	}
123	
124	/// Finds JSX or an element factory call that can be part of an expression's value: through conditionals, logical
125	/// operators, arrays and call arguments (`items.map(i => <li/>)`, `createPortal(<div/>, el)`), but not inside an object
126	/// literal, whose JSX is a property's value rather than the expression's.
127	struct ElementInValue<'s> {
128	    found: bool,
129	    scope: &'s dyn Scope,
130	}
131	
132	impl<'a> Visit<'a> for ElementInValue<'_> {
133	    fn visit_jsx_element(&mut self, _it: &JSXElement<'a>) {
134	        self.found = true;
135	    }
136	
137	    fn visit_jsx_fragment(&mut self, _it: &JSXFragment<'a>) {
138	        self.found = true;
139	    }
140	
141	    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
142	        let callee = super::component::callee_of(it);
143	        let name = callee.and_then(callee_name);
144	        let calls_helper = matches!(callee, Some(Expression::Identifier(id)) if self.scope.is_element_helper(&id.name));
145	        if calls_helper || callee.is_some_and(|callee| is_element_factory_callee(callee, self.scope)) {
146	            self.found = true;
147	        // These calls preserve the JSX value; an arbitrary call may turn it into a Response or other data.
148	        } else if name.is_some_and(|name| matches!(name, "map" | "flatMap" | "reduce"))
149	            || matches!(callee, Some(Expression::StaticMemberExpression(member))
150	                if matches!(
151	                    super::component::named(&member.object),
152	                    Some(Expression::Identifier(id)) if id.name == "Promise"
153	                ) && matches!(member.property.name.as_str(), "resolve" | "all"))
154	        {
155	            walk::walk_call_expression(self, it);
156	        }
157	    }
158	
159	    // JSX passed to a constructor, such as `new ImageResponse(<div />)`, is not the function's return value.
160	    fn visit_new_expression(&mut self, _it: &NewExpression<'a>) {}
161	
162	    fn visit_object_expression(&mut self, _it: &ObjectExpression<'a>) {}
163	}
164	
165	fn value_has_element(expr: &Expression<'_>, scope: &dyn Scope) -> bool {
166	    let mut finder = ElementInValue { found: false, scope };
167	    finder.visit_expression(expr);
168	    finder.found
169	}
170	
171	/// What one returned value says about the function.
172	fn returns_element(expr: &Expression<'_>, element_locals: &FxHashSet<String>, scope: &dyn Scope) -> bool {
173	    match expr.without_parentheses() {
174	        // Rendering nothing is a valid render.
175	        Expression::NullLiteral(_) => true,
176	        Expression::Identifier(id) if element_locals.contains(id.name.as_str()) => true,
177	        // A component invoked directly: `return JoinList({ ... })`.
178	        Expression::CallExpression(call)
179	            if super::component::callee_of(call).and_then(callee_name).is_some_and(super::is_pascal_case) =>
180	        {
181	            true
182	        }
183	        e if is_children(e) => true,
184	        e => value_has_element(e, scope),
185	    }
186	}
187	
188	/// Walks one function's own body, not nested functions: its `return`s, its top-level hook calls, and the local
189	/// variables it initializes with an element (`const content = <div/>; return content`).
190	/// A local is declared before the `return` that uses it, so each `return` is judged as it is reached.
191	struct OwnBody<'s> {
192	    returns_element: bool,
193	    element_locals: FxHashSet<String>,
194	    calls_hook: bool,
195	    nested: u32,
196	    scope: &'s dyn Scope,
197	}
198	
199	impl<'s> OwnBody<'s> {
200	    fn new(scope: &'s dyn Scope) -> Self {
201	        Self { returns_element: false, element_locals: FxHashSet::default(), calls_hook: false, nested: 0, scope }
202	    }
203	}
204	
205	impl<'a> Visit<'a> for OwnBody<'_> {
206	    fn visit_return_statement(&mut self, it: &ReturnStatement<'a>) {
207	        if self.nested == 0
208	            && it.argument.as_ref().is_some_and(|r| returns_element(r, &self.element_locals, self.scope))
209	        {
210	            self.returns_element = true;
211	        }
212	        walk::walk_return_statement(self, it);
213	    }
214	
215	    fn visit_variable_declarator(&mut self, it: &VariableDeclarator<'a>) {
216	        if self.nested == 0
217	            && let (BindingPattern::BindingIdentifier(id), Some(init)) = (&it.id, &it.init)
218	            && value_has_element(init, self.scope)
219	        {
220	            self.element_locals.insert(id.name.to_string());
221	        }
222	        walk::walk_variable_declarator(self, it);
223	    }
224	
225	    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
226	        if self.nested == 0 && super::component::callee_of(it).and_then(callee_name).is_some_and(is_hook_name) {
227	            self.calls_hook = true;
228	        }
229	        walk::walk_call_expression(self, it);
230	    }
231	
232	    fn visit_function(&mut self, it: &Function<'a>, flags: ScopeFlags) {
233	        self.nested += 1;
234	        walk::walk_function(self, it, flags);
235	        self.nested -= 1;
236	    }
237	
238	    fn visit_arrow_function_expression(&mut self, it: &ArrowFunctionExpression<'a>) {
239	        self.nested += 1;
240	        walk::walk_arrow_function_expression(self, it);
241	        self.nested -= 1;
242	    }
243	}
244	
245	/// A function body: a block, or an arrow's single expression or block.
246	pub(super) enum Body<'b, 'a> {
247	    Block(&'b FunctionBody<'a>),
248	    /// An arrow's body, and whether it is a single expression (`=> <div/>`) rather than a block.
249	    Arrow(&'b ArrowFunctionBody<'a>, bool),
250	}
251	
252	/// The parts of a function that decide whether it renders.
253	pub(super) struct FunctionShape<'b, 'a> {
254	    pub generator: bool,
255	    pub return_type: Option<&'b TSTypeAnnotation<'a>>,
256	    pub body: Option<Body<'b, 'a>>,
257	}
258	
259	impl<'b, 'a> FunctionShape<'b, 'a> {
260	    pub(super) fn of_arrow(f: &'b ArrowFunctionExpression<'a>) -> Self {
261	        Self {
262	            generator: false,
263	            return_type: f.return_type.as_deref(),
264	            body: Some(Body::Arrow(&f.body, f.is_expression())),
265	        }
266	    }
267	
268	    pub(super) fn of_function(f: &'b Function<'a>) -> Self {
269	        Self { generator: f.generator, return_type: f.return_type.as_deref(), body: f.body.as_deref().map(Body::Block) }
270	    }
271	}
272	
273	/// `Ok` when the function renders; `Err` with the reason it does not.
274	pub(super) fn renders(shape: &FunctionShape<'_, '_>, react: ReactBinding<'_>) -> Result<(), NoRender> {
275	    if shape.generator {
276	        return Err("is a generator");
277	    }
278	    if let Some(annotation) = shape.return_type {
279	        return if type_renders(&annotation.type_annotation, react) {
280	            Ok(())
281	        } else {
282	            Err("declares a return type that is not React's element type")
283	        };
284	    }
285	    let renders = match &shape.body {
286	        None => return Err("has no body and no element return type"),
287	        Some(Body::Arrow(body, true)) => {
288	            body.as_expression().is_some_and(|expr| returns_element(expr, &FxHashSet::default(), react))
289	        }
290	        Some(Body::Arrow(body, false)) => {
291	            let mut own = OwnBody::new(react);
292	            own.visit_arrow_function_body(body);
293	            own.calls_hook || own.returns_element
294	        }
295	        Some(Body::Block(body)) => {
296	            let mut own = OwnBody::new(react);
297	            own.visit_function_body(body);
298	            own.calls_hook || own.returns_element
299	        }
300	    };
301	    if renders {
302	        Ok(())
303	    } else {
304	        Err("never returns an element: no returned JSX, element, null, children or component call, and no hook call")
305	    }
306	}
307	
308	/// Names of module-level functions whose declared return type is an element, which makes a call to them element
309	/// evidence: `renderByProp(render, props, <button />)` with `renderByProp(...): React.ReactElement`. Judged on the
310	/// declaration alone, so a helper that returns something else without saying so is not counted.
311	pub(super) fn element_helpers(program: &Program<'_>) -> FxHashSet<String> {
312	    let mut foreign = FxHashSet::default();
313	    for stmt in &program.body {
314	        if let Statement::ImportDeclaration(import) = stmt
315	            && !super::is_react_module(&super::js_text::lossy(import.source.value))
316	        {
317	            for spec in import.specifiers.iter().flatten() {
318	                foreign.insert(spec.local().name.to_string());
319	            }
320	        }
321	    }
322	    let react = Foreign(&foreign);
323	    let declarations: Vec<&Declaration<'_>> = program.body.iter().filter_map(|stmt| stmt.as_declaration()).collect();
324	
325	    // `type Output = React.ReactElement` and aliases of aliases.
326	    let mut aliases = FxHashSet::default();
327	    loop {
328	        let before = aliases.len();
329	        for declaration in &declarations {
330	            if let Declaration::TSTypeAliasDeclaration(alias) = declaration
331	                && names_element(&alias.type_annotation, &react, &aliases)
332	            {
333	                aliases.insert(alias.id.name.to_string());
334	            }
335	        }
336	        if aliases.len() == before {
337	            break;
338	        }
339	    }
340	
341	    let returns_element = |annotation: Option<&TSTypeAnnotation<'_>>| {
342	        annotation.is_some_and(|a| names_element(&a.type_annotation, &react, &aliases))
343	    };
344	    let mut helpers = FxHashSet::default();
345	    for declaration in declarations {
346	        match declaration {
347	            Declaration::FunctionDeclaration(f) => {
348	                if let Some(id) = f.id.as_ref().filter(|_| returns_element(f.return_type.as_deref())) {
349	                    helpers.insert(id.name.to_string());
350	                }
351	            }
352	            Declaration::VariableDeclaration(vars) => {
353	                for declarator in &vars.declarations {
354	                    let (BindingPattern::BindingIdentifier(id), Some(init)) = (&declarator.id, &declarator.init) else {
355	                        continue;
356	                    };
357	                    let annotation = match init.without_parentheses() {
358	                        Expression::ArrowFunctionExpression(f) => f.return_type.as_deref(),
359	                        Expression::FunctionExpression(f) => f.return_type.as_deref(),
360	                        _ => None,
361	                    };
362	                    if returns_element(annotation) {
363	                        helpers.insert(id.name.to_string());
364	                    }
365	                }
366	            }
367	            _ => {}
368	        }
369	    }
370	    helpers
371	}
372	
373	/// The imports that are not React's, seen before the file is walked.
374	struct Foreign<'f>(&'f FxHashSet<String>);
375	
376	impl Scope for Foreign<'_> {
377	    fn may_be_react(&self, name: &str) -> bool {
378	        !self.0.contains(name)
379	    }
380	
381	    fn is_preact_h(&self, _receiver: Option<&str>) -> bool {
382	        false
383	    }
384	
385	    fn is_element_helper(&self, _name: &str) -> bool {
386	        false
387	    }
388	
389	    fn is_react_wrapper(&self, _call: &CallExpression<'_>) -> bool {
390	        false
391	    }
392	}
393	
394	/// Whether a type is an element type or a local alias of one. A `Promise` of one is not: the call returns the promise.
395	fn names_element(ty: &TSType<'_>, react: ReactBinding<'_>, aliases: &FxHashSet<String>) -> bool {
396	    match ty {
397	        TSType::TSTypeReference(r) => match &r.type_name {
398	            TSTypeName::IdentifierReference(id) if aliases.contains(id.name.as_str()) => true,
399	            name => {
400	                leftmost_and_rightmost(name).is_some_and(|(_, right)| right != "Promise") && type_renders(ty, react)
401	            }
402	        },
403	        TSType::TSUnionType(u) => u.types.iter().any(|t| names_element(t, react, aliases)),
404	        TSType::TSParenthesizedType(p) => names_element(&p.type_annotation, react, aliases),
405	        _ => false,
406	    }
407	}
