//! Evidence that a function renders, so a typed PascalCase function is a component and not a helper that happens to
//! take an object. A typed first parameter alone admits `FormatName = (u: User) => string`, `debounce((q: Row) => …)`
//! and selectors, so every rule that infers a component from a function asks this first.
//!
//! What the function returns decides, not what appears anywhere in its body: JSX built in a nested callback or never
//! returned is not evidence.

use oxc_ast::ast::*;
use oxc_ast_visit::{Visit, walk};
use oxc_syntax::scope::ScopeFlags;
use rustc_hash::FxHashSet;

/// Why a function was judged not to render. Carried into the skip diagnostic.
pub(super) type NoRender = &'static str;

/// Names whose type, as a return annotation, means the function renders.
const ELEMENT_TYPE_NAMES: &[&str] = &["Element", "ReactElement", "ReactNode", "ReactPortal", "JSX"];

/// Callees that produce an element, by name. Preact's `h` is not here: so short a name proves nothing until it is
/// known to be imported from Preact (`Scope::is_preact_h`).
const ELEMENT_FACTORIES: &[&str] = &["createElement", "cloneElement", "jsx", "jsxs", "jsxDEV", "createPortal"];

/// Whether a callee name names an element factory, given the receiver it was called on (`Preact` in `Preact.h(…)`).
/// `h` counts only as Preact's own binding, bare or on Preact's namespace: `codec.h(…)` and a local helper called `h`
/// are not factories.
pub(super) fn is_element_factory_name(name: &str, receiver: Option<&str>, scope: &dyn Scope) -> bool {
    if name == "h" {
        return scope.is_preact_h(receiver);
    }
    ELEMENT_FACTORIES.contains(&name)
}

/// Whether a call's callee is an element factory: see [`is_element_factory_name`].
pub(super) fn is_element_factory_callee(callee: &Expression<'_>, scope: &dyn Scope) -> bool {
    match callee {
        Expression::Identifier(id) => is_element_factory_name(id.name.as_str(), None, scope),
        Expression::StaticMemberExpression(m) => {
            let receiver = match super::component::named(&m.object) {
                Some(Expression::Identifier(object)) => Some(object.name.as_str()),
                _ => Some(""),
            };
            is_element_factory_name(m.property.name.as_str(), receiver, scope)
        }
        _ => false,
    }
}

/// Whether a type name, as written in this file, can be React's or the global `JSX` namespace's. Given the name's
/// leftmost segment (`React` for `React.ReactNode`), so an element-like name imported from another module does not
/// count.
pub(super) type ReactBinding<'f> = &'f dyn Scope;

/// What the file around a function says about the names it uses.
pub(super) trait Scope {
    /// Whether a type name can be React's: see [`ReactBinding`].
    fn may_be_react(&self, name: &str) -> bool;
    /// Whether a call to this name returns an element: a same-file function declared to return one.
    fn is_element_helper(&self, name: &str) -> bool;
    /// Whether the call is React's `memo(…)` or `forwardRef(…)`, by where its callee was imported from.
    fn is_react_wrapper(&self, call: &CallExpression<'_>) -> bool;
    /// Whether `h` called bare (`receiver` is `None`) or on `receiver` (`Preact.h`) is Preact's, by where it was
    /// imported from.
    fn is_preact_h(&self, receiver: Option<&str>) -> bool;
}

fn leftmost_and_rightmost<'n>(name: &'n TSTypeName<'_>) -> Option<(&'n str, &'n str)> {
    match name {
        TSTypeName::IdentifierReference(id) => Some((id.name.as_str(), id.name.as_str())),
        TSTypeName::QualifiedName(q) => {
            let mut left = &q.left;
            while let TSTypeName::QualifiedName(inner) = left {
                left = &inner.left;
            }
            match left {
                TSTypeName::IdentifierReference(id) => Some((id.name.as_str(), q.right.name.as_str())),
                _ => None,
            }
        }
        _ => None,
    }
}

/// Whether a return type annotation names a renderable result bound to React: `JSX.Element`, `ReactNode`,
/// `ReactElement`, a union containing one, or `Promise` of one (async server components).
pub(super) fn type_renders(ty: &TSType<'_>, react: ReactBinding<'_>) -> bool {
    match ty {
        TSType::TSTypeReference(r) => {
            let Some((left, right)) = leftmost_and_rightmost(&r.type_name) else { return false };
            if right == "Promise" {
                return r
                    .type_arguments
                    .as_ref()
                    .and_then(|a| a.params.first())
                    .is_some_and(|t| type_renders(t, react));
            }
            ELEMENT_TYPE_NAMES.contains(&right) && react.may_be_react(left)
        }
        TSType::TSUnionType(u) => u.types.iter().any(|t| type_renders(t, react)),
        TSType::TSParenthesizedType(p) => type_renders(&p.type_annotation, react),
        _ => false,
    }
}

fn callee_name<'n>(callee: &'n Expression<'_>) -> Option<&'n str> {
    match callee {
        Expression::Identifier(id) => Some(id.name.as_str()),
        Expression::StaticMemberExpression(m) => Some(m.property.name.as_str()),
        _ => None,
    }
}

fn is_hook_name(name: &str) -> bool {
    name.strip_prefix("use").is_some_and(|rest| rest.starts_with(|c: char| c.is_ascii_uppercase()))
}

fn is_children(expr: &Expression<'_>) -> bool {
    match expr {
        Expression::Identifier(id) => id.name == "children",
        Expression::StaticMemberExpression(m) => m.property.name == "children",
        _ => false,
    }
}

/// Finds JSX or an element factory call that can be part of an expression's value: through conditionals, logical
/// operators, arrays and call arguments (`items.map(i => <li/>)`, `createPortal(<div/>, el)`), but not inside an object
/// literal, whose JSX is a property's value rather than the expression's.
struct ElementInValue<'s> {
    found: bool,
    scope: &'s dyn Scope,
}

impl<'a> Visit<'a> for ElementInValue<'_> {
    fn visit_jsx_element(&mut self, _it: &JSXElement<'a>) {
        self.found = true;
    }

    fn visit_jsx_fragment(&mut self, _it: &JSXFragment<'a>) {
        self.found = true;
    }

    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
        let callee = super::component::callee_of(it);
        let name = callee.and_then(callee_name);
        let calls_helper = matches!(callee, Some(Expression::Identifier(id)) if self.scope.is_element_helper(&id.name));
        if calls_helper || callee.is_some_and(|callee| is_element_factory_callee(callee, self.scope)) {
            self.found = true;
        // These calls preserve the JSX value; an arbitrary call may turn it into a Response or other data.
        } else if name.is_some_and(|name| matches!(name, "map" | "flatMap" | "reduce"))
            || matches!(callee, Some(Expression::StaticMemberExpression(member))
                if matches!(
                    super::component::named(&member.object),
                    Some(Expression::Identifier(id)) if id.name == "Promise"
                ) && matches!(member.property.name.as_str(), "resolve" | "all"))
        {
            walk::walk_call_expression(self, it);
        }
    }

    // JSX passed to a constructor, such as `new ImageResponse(<div />)`, is not the function's return value.
    fn visit_new_expression(&mut self, _it: &NewExpression<'a>) {}

    fn visit_object_expression(&mut self, _it: &ObjectExpression<'a>) {}
}

fn value_has_element(expr: &Expression<'_>, scope: &dyn Scope) -> bool {
    let mut finder = ElementInValue { found: false, scope };
    finder.visit_expression(expr);
    finder.found
}

/// What one returned value says about the function.
fn returns_element(expr: &Expression<'_>, element_locals: &FxHashSet<String>, scope: &dyn Scope) -> bool {
    match expr.without_parentheses() {
        // Rendering nothing is a valid render.
        Expression::NullLiteral(_) => true,
        Expression::Identifier(id) if element_locals.contains(id.name.as_str()) => true,
        // A component invoked directly: `return JoinList({ ... })`.
        Expression::CallExpression(call)
            if super::component::callee_of(call).and_then(callee_name).is_some_and(super::is_pascal_case) =>
        {
            true
        }
        e if is_children(e) => true,
        e => value_has_element(e, scope),
    }
}

/// Walks one function's own body, not nested functions: its `return`s, its top-level hook calls, and the local
/// variables it initializes with an element (`const content = <div/>; return content`).
/// A local is declared before the `return` that uses it, so each `return` is judged as it is reached.
struct OwnBody<'s> {
    returns_element: bool,
    element_locals: FxHashSet<String>,
    calls_hook: bool,
    nested: u32,
    scope: &'s dyn Scope,
}

impl<'s> OwnBody<'s> {
    fn new(scope: &'s dyn Scope) -> Self {
        Self { returns_element: false, element_locals: FxHashSet::default(), calls_hook: false, nested: 0, scope }
    }
}

impl<'a> Visit<'a> for OwnBody<'_> {
    fn visit_return_statement(&mut self, it: &ReturnStatement<'a>) {
        if self.nested == 0
            && it.argument.as_ref().is_some_and(|r| returns_element(r, &self.element_locals, self.scope))
        {
            self.returns_element = true;
        }
        walk::walk_return_statement(self, it);
    }

    fn visit_variable_declarator(&mut self, it: &VariableDeclarator<'a>) {
        if self.nested == 0
            && let (BindingPattern::BindingIdentifier(id), Some(init)) = (&it.id, &it.init)
            && value_has_element(init, self.scope)
        {
            self.element_locals.insert(id.name.to_string());
        }
        walk::walk_variable_declarator(self, it);
    }

    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
        if self.nested == 0 && super::component::callee_of(it).and_then(callee_name).is_some_and(is_hook_name) {
            self.calls_hook = true;
        }
        walk::walk_call_expression(self, it);
    }

    fn visit_function(&mut self, it: &Function<'a>, flags: ScopeFlags) {
        self.nested += 1;
        walk::walk_function(self, it, flags);
        self.nested -= 1;
    }

    fn visit_arrow_function_expression(&mut self, it: &ArrowFunctionExpression<'a>) {
        self.nested += 1;
        walk::walk_arrow_function_expression(self, it);
        self.nested -= 1;
    }
}

/// A function body: a block, or an arrow's single expression or block.
pub(super) enum Body<'b, 'a> {
    Block(&'b FunctionBody<'a>),
    /// An arrow's body, and whether it is a single expression (`=> <div/>`) rather than a block.
    Arrow(&'b ArrowFunctionBody<'a>, bool),
}

/// The parts of a function that decide whether it renders.
pub(super) struct FunctionShape<'b, 'a> {
    pub generator: bool,
    pub return_type: Option<&'b TSTypeAnnotation<'a>>,
    pub body: Option<Body<'b, 'a>>,
}

impl<'b, 'a> FunctionShape<'b, 'a> {
    pub(super) fn of_arrow(f: &'b ArrowFunctionExpression<'a>) -> Self {
        Self {
            generator: false,
            return_type: f.return_type.as_deref(),
            body: Some(Body::Arrow(&f.body, f.is_expression())),
        }
    }

    pub(super) fn of_function(f: &'b Function<'a>) -> Self {
        Self { generator: f.generator, return_type: f.return_type.as_deref(), body: f.body.as_deref().map(Body::Block) }
    }
}

/// `Ok` when the function renders; `Err` with the reason it does not.
pub(super) fn renders(shape: &FunctionShape<'_, '_>, react: ReactBinding<'_>) -> Result<(), NoRender> {
    if shape.generator {
        return Err("is a generator");
    }
    if let Some(annotation) = shape.return_type {
        return if type_renders(&annotation.type_annotation, react) {
            Ok(())
        } else {
            Err("declares a return type that is not React's element type")
        };
    }
    let renders = match &shape.body {
        None => return Err("has no body and no element return type"),
        Some(Body::Arrow(body, true)) => {
            body.as_expression().is_some_and(|expr| returns_element(expr, &FxHashSet::default(), react))
        }
        Some(Body::Arrow(body, false)) => {
            let mut own = OwnBody::new(react);
            own.visit_arrow_function_body(body);
            own.calls_hook || own.returns_element
        }
        Some(Body::Block(body)) => {
            let mut own = OwnBody::new(react);
            own.visit_function_body(body);
            own.calls_hook || own.returns_element
        }
    };
    if renders {
        Ok(())
    } else {
        Err("never returns an element: no returned JSX, element, null, children or component call, and no hook call")
    }
}

/// Names of module-level functions whose declared return type is an element, which makes a call to them element
/// evidence: `renderByProp(render, props, <button />)` with `renderByProp(...): React.ReactElement`. Judged on the
/// declaration alone, so a helper that returns something else without saying so is not counted.
pub(super) fn element_helpers(program: &Program<'_>) -> FxHashSet<String> {
    let mut foreign = FxHashSet::default();
    for stmt in &program.body {
        if let Statement::ImportDeclaration(import) = stmt
            && !super::is_react_module(&super::js_text::lossy(import.source.value))
        {
            for spec in import.specifiers.iter().flatten() {
                foreign.insert(spec.local().name.to_string());
            }
        }
    }
    let react = Foreign(&foreign);
    let declarations: Vec<&Declaration<'_>> = program.body.iter().filter_map(|stmt| stmt.as_declaration()).collect();

    // `type Output = React.ReactElement` and aliases of aliases.
    let mut aliases = FxHashSet::default();
    loop {
        let before = aliases.len();
        for declaration in &declarations {
            if let Declaration::TSTypeAliasDeclaration(alias) = declaration
                && names_element(&alias.type_annotation, &react, &aliases)
            {
                aliases.insert(alias.id.name.to_string());
            }
        }
        if aliases.len() == before {
            break;
        }
    }

    let returns_element = |annotation: Option<&TSTypeAnnotation<'_>>| {
        annotation.is_some_and(|a| names_element(&a.type_annotation, &react, &aliases))
    };
    let mut helpers = FxHashSet::default();
    for declaration in declarations {
        match declaration {
            Declaration::FunctionDeclaration(f) => {
                if let Some(id) = f.id.as_ref().filter(|_| returns_element(f.return_type.as_deref())) {
                    helpers.insert(id.name.to_string());
                }
            }
            Declaration::VariableDeclaration(vars) => {
                for declarator in &vars.declarations {
                    let (BindingPattern::BindingIdentifier(id), Some(init)) = (&declarator.id, &declarator.init) else {
                        continue;
                    };
                    let annotation = match init.without_parentheses() {
                        Expression::ArrowFunctionExpression(f) => f.return_type.as_deref(),
                        Expression::FunctionExpression(f) => f.return_type.as_deref(),
                        _ => None,
                    };
                    if returns_element(annotation) {
                        helpers.insert(id.name.to_string());
                    }
                }
            }
            _ => {}
        }
    }
    helpers
}

/// The imports that are not React's, seen before the file is walked.
struct Foreign<'f>(&'f FxHashSet<String>);

impl Scope for Foreign<'_> {
    fn may_be_react(&self, name: &str) -> bool {
        !self.0.contains(name)
    }

    fn is_preact_h(&self, _receiver: Option<&str>) -> bool {
        false
    }

    fn is_element_helper(&self, _name: &str) -> bool {
        false
    }

    fn is_react_wrapper(&self, _call: &CallExpression<'_>) -> bool {
        false
    }
}

/// Whether a type is an element type or a local alias of one. A `Promise` of one is not: the call returns the promise.
fn names_element(ty: &TSType<'_>, react: ReactBinding<'_>, aliases: &FxHashSet<String>) -> bool {
    match ty {
        TSType::TSTypeReference(r) => match &r.type_name {
            TSTypeName::IdentifierReference(id) if aliases.contains(id.name.as_str()) => true,
            name => {
                leftmost_and_rightmost(name).is_some_and(|(_, right)| right != "Promise") && type_renders(ty, react)
            }
        },
        TSType::TSUnionType(u) => u.types.iter().any(|t| names_element(t, react, aliases)),
        TSType::TSParenthesizedType(p) => names_element(&p.type_annotation, react, aliases),
        _ => false,
    }
}

//! Component detection: FC annotation, forwardRef, HOC-wrapped, ForwardRefExoticComponent.

use std::collections::BTreeMap;

use camino::Utf8Path;
use compact_str::CompactString;
use oxc_ast::ast::*;
use rustc_hash::FxHashMap;

use crate::types::{CollectedTypeAlias, ComponentMapping, DetectionRule, DiagnosticCode};

use super::evidence::{FunctionShape, Scope, renders};
use super::{ReactApi, SourceDataCollector, is_pascal_case};

/// One layer of the wrappers TypeScript erases from a value.
enum Wrapper<'b, 'a> {
    /// Parentheses, `satisfies` or `!`: the value and its type pass through.
    Transparent(&'b Expression<'a>),
    /// `as` or `<T>x`: the value passes through, its type is replaced by the one asserted.
    Asserted(&'b Expression<'a>, &'b TSType<'a>),
    /// `f<T>`: the value passes through with its type arguments given.
    Instantiation(&'b TSInstantiationExpression<'a>),
}

/// The wrapper `expr` is, if it is one. The one list of what a wrapper is, and exhaustive so that a new expression kind
/// in an OXC release has to be placed here before it compiles.
fn wrapper<'a, 'b>(expr: &'b Expression<'a>) -> Option<Wrapper<'b, 'a>> {
    match expr {
        Expression::ParenthesizedExpression(inner) => Some(Wrapper::Transparent(&inner.expression)),
        Expression::TSSatisfiesExpression(inner) => Some(Wrapper::Transparent(&inner.expression)),
        Expression::TSNonNullExpression(inner) => Some(Wrapper::Transparent(&inner.expression)),
        Expression::TSAsExpression(inner) => Some(Wrapper::Asserted(&inner.expression, &inner.type_annotation)),
        Expression::TSTypeAssertion(inner) => Some(Wrapper::Asserted(&inner.expression, &inner.type_annotation)),
        Expression::TSInstantiationExpression(inner) => Some(Wrapper::Instantiation(inner)),
        Expression::BooleanLiteral(_)
        | Expression::NullLiteral(_)
        | Expression::NumericLiteral(_)
        | Expression::BigIntLiteral(_)
        | Expression::RegExpLiteral(_)
        | Expression::StringLiteral(_)
        | Expression::TemplateLiteral(_)
        | Expression::Identifier(_)
        | Expression::Super(_)
        | Expression::ArrayExpression(_)
        | Expression::ArrowFunctionExpression(_)
        | Expression::AssignmentExpression(_)
        | Expression::AwaitExpression(_)
        | Expression::BinaryExpression(_)
        | Expression::CallExpression(_)
        | Expression::ChainExpression(_)
        | Expression::ClassExpression(_)
        | Expression::ConditionalExpression(_)
        | Expression::FunctionExpression(_)
        | Expression::ImportExpression(_)
        | Expression::LogicalExpression(_)
        | Expression::NewExpression(_)
        | Expression::ObjectExpression(_)
        | Expression::SequenceExpression(_)
        | Expression::TaggedTemplateExpression(_)
        | Expression::ThisExpression(_)
        | Expression::UnaryExpression(_)
        | Expression::UpdateExpression(_)
        | Expression::YieldExpression(_)
        | Expression::PrivateInExpression(_)
        | Expression::ImportMeta(_)
        | Expression::NewTarget(_)
        | Expression::JSXElement(_)
        | Expression::JSXFragment(_)
        | Expression::V8IntrinsicExpression(_)
        | Expression::ComputedMemberExpression(_)
        | Expression::StaticMemberExpression(_)
        | Expression::PrivateFieldExpression(_) => None,
    }
}

/// A value beneath its wrappers: component libraries cast a forwardRef or HOC call to a hand-rolled component type
/// (Fluent UI: "required due to lack of distributive union to support unions on @types/react"), or check it with
/// `satisfies`. An instantiation is kept: `const X = Base<P>` is not `Base`, and reading it as `Base` drops `P`.
pub(super) fn peel_expr<'a, 'b>(mut expr: &'b Expression<'a>) -> &'b Expression<'a> {
    loop {
        expr = match wrapper(expr) {
            Some(Wrapper::Transparent(inner) | Wrapper::Asserted(inner, _)) => inner,
            Some(Wrapper::Instantiation(_)) | None => return expr,
        };
    }
}

/// What the outermost assertion on a callee, or on the namespace it is read from, says about calling it. Only the
/// outermost one counts: `(e as A) as B` has type `B` whatever `A` is. An assertion declines a candidate only on
/// affirmative evidence ([`Evidence::NotRenderable`]); a type the extractor cannot read leaves the call the candidate
/// its name makes it ([`Evidence::Unknown`]), as before assertions were read at all.
#[derive(Clone, Copy)]
pub(super) enum Evidence<'b, 'a> {
    /// No assertion, or one that keeps the callee's own type: `typeof` the same expression, `any` and `unknown`. The
    /// callee's declaration describes the call.
    Identity,
    /// A type reference (`(forwardRef as forwardRefType)`). The file may alias it to `typeof` the callee
    /// (`SourceDataCollector::describes_call`); otherwise it reads as [`Evidence::Unknown`].
    Reference(&'b TSTypeReference<'a>),
    /// Every call signature of the asserted type returns what no component or element is ([`Returns::NotRenderable`]):
    /// `(Object as (v: object) => object)(…)` is no component, whatever its name.
    NotRenderable,
    /// Anything else: `typeof` another expression, a signature whose result may render or is not read, a type with no
    /// call signature. The name still says what the call is; the callee's declaration no longer describes it.
    Unknown,
}

/// An expression beneath every wrapper, instantiations included, the type arguments an instantiation among them gave
/// it, and what the outermost assertion says about calling it.
#[derive(Clone, Copy)]
pub(super) struct Peeled<'b, 'a> {
    pub(super) expr: &'b Expression<'a>,
    /// The outermost instantiation's type arguments, unless an assertion above it replaced its type: `(f<T>)` and
    /// `(f<T>)!` give `T`; `(f<T> as G)` gives none, as the value then has type `G`.
    pub(super) type_arguments: Option<&'b TSTypeParameterInstantiation<'a>>,
    pub(super) evidence: Evidence<'b, 'a>,
}

impl<'b, 'a> Peeled<'b, 'a> {
    /// `expr`, when what it is called still says what the call is (`forwardRef`, `memo`, `Object.assign`, a PascalCase
    /// component): always, unless the assertion gives the call a result no component has.
    pub(super) fn named(&self) -> Option<&'b Expression<'a>> {
        match self.evidence {
            Evidence::NotRenderable => None,
            Evidence::Identity | Evidence::Reference(_) | Evidence::Unknown => Some(self.expr),
        }
    }
}

/// The value beneath `expr`'s wrappers, the outermost instantiation's type arguments when no assertion is above them,
/// and the outermost assertion. One pass over the wrappers, so a chain of them costs its length.
fn layers<'a, 'b>(
    mut expr: &'b Expression<'a>,
) -> (&'b Expression<'a>, Option<&'b TSTypeParameterInstantiation<'a>>, Option<&'b TSType<'a>>) {
    let mut type_arguments = None;
    let mut outermost = None;
    loop {
        #[cfg(test)]
        steps::count();
        expr = match wrapper(expr) {
            Some(Wrapper::Transparent(inner)) => inner,
            Some(Wrapper::Asserted(inner, ty)) => {
                outermost = outermost.or(Some(ty));
                inner
            }
            Some(Wrapper::Instantiation(instantiation)) => {
                if outermost.is_none() && type_arguments.is_none() {
                    type_arguments = Some(&*instantiation.type_arguments);
                }
                &instantiation.expression
            }
            None => return (expr, type_arguments, outermost),
        };
    }
}

/// See [`Peeled`]. For what a callee or an `extends` target is: OXC 0.159 keeps `(f<T>)(x)` and `extends (B<T>)` as an
/// instantiation node beneath the call or heritage clause, where 0.158 moved its type arguments onto them.
pub(super) fn peel<'a, 'b>(expr: &'b Expression<'a>) -> Peeled<'b, 'a> {
    let (expr, type_arguments, outermost) = layers(expr);
    let evidence = match (outermost, expr) {
        (Some(ty), _) => asserted(ty, expr),
        // `(React as { forwardRef: typeof React.forwardRef }).forwardRef`: the namespace's assertion gives the member
        // the type it declares for it.
        (None, Expression::StaticMemberExpression(member)) => match receiver(&member.object) {
            Typed::Own => Evidence::Identity,
            Typed::Asserted(ty) => member_evidence(ty, member.property.name.as_str(), expr),
            Typed::Unread => Evidence::Unknown,
        },
        (None, _) => Evidence::Identity,
    };
    Peeled { expr, type_arguments, evidence }
}

/// The type a namespace has, as far as the assertions on it and on the namespaces it is read from say.
enum Typed<'b, 'a> {
    /// Its own: no assertion, or one that keeps it.
    Own,
    /// The asserted type, or the type an asserted namespace's type literal declares for the member.
    Asserted(&'b TSType<'a>),
    /// A member the asserted type does not declare where the extractor looks (a type literal's property).
    Unread,
}

fn receiver<'a, 'b>(expr: &'b Expression<'a>) -> Typed<'b, 'a> {
    let (expr, _, outermost) = layers(expr);
    let declared = match (outermost, expr) {
        (Some(ty), _) => Some(ty),
        (None, Expression::StaticMemberExpression(object)) => match receiver(&object.object) {
            Typed::Own => None,
            Typed::Asserted(ty) => match member(ty, object.property.name.as_str()) {
                Member::Property(ty) => Some(ty),
                Member::Methods(_) | Member::Unread => return Typed::Unread,
            },
            Typed::Unread => return Typed::Unread,
        },
        (None, _) => None,
    };
    match declared {
        None => Typed::Own,
        Some(ty) if matches!(asserted(ty, expr), Evidence::Identity) => Typed::Own,
        Some(ty) => Typed::Asserted(ty),
    }
}

/// What a type literal declares for a member.
enum Member<'b, 'a> {
    Property(&'b TSType<'a>),
    /// The literal declares the member as methods (`{ memo(c: C): R }`): their signatures are its type.
    Methods(&'b TSTypeLiteral<'a>),
    Unread,
}

fn names_key(key: &PropertyKey<'_>, name: &str) -> bool {
    key.static_name().is_some_and(|key| super::js_text::property_name(&key) == name)
}

fn member<'a, 'b>(ty: &'b TSType<'a>, name: &str) -> Member<'b, 'a> {
    match ty {
        TSType::TSParenthesizedType(inner) => member(&inner.type_annotation, name),
        TSType::TSTypeLiteral(literal) => {
            for signature in &literal.members {
                match signature {
                    TSSignature::TSPropertySignature(property) if names_key(&property.key, name) => {
                        return property
                            .type_annotation
                            .as_ref()
                            .map_or(Member::Unread, |annotation| Member::Property(&annotation.type_annotation));
                    }
                    TSSignature::TSMethodSignature(method)
                        if method.kind == TSMethodSignatureKind::Method && names_key(&method.key, name) =>
                    {
                        return Member::Methods(literal);
                    }
                    TSSignature::TSPropertySignature(_)
                    | TSSignature::TSMethodSignature(_)
                    | TSSignature::TSIndexSignature(_)
                    | TSSignature::TSCallSignatureDeclaration(_)
                    | TSSignature::TSConstructSignatureDeclaration(_) => {}
                }
            }
            Member::Unread
        }
        TSType::TSAnyKeyword(_)
        | TSType::TSBigIntKeyword(_)
        | TSType::TSBooleanKeyword(_)
        | TSType::TSIntrinsicKeyword(_)
        | TSType::TSNeverKeyword(_)
        | TSType::TSNullKeyword(_)
        | TSType::TSNumberKeyword(_)
        | TSType::TSObjectKeyword(_)
        | TSType::TSStringKeyword(_)
        | TSType::TSSymbolKeyword(_)
        | TSType::TSUndefinedKeyword(_)
        | TSType::TSUnknownKeyword(_)
        | TSType::TSVoidKeyword(_)
        | TSType::TSArrayType(_)
        | TSType::TSConditionalType(_)
        | TSType::TSConstructorType(_)
        | TSType::TSFunctionType(_)
        | TSType::TSImportType(_)
        | TSType::TSIndexedAccessType(_)
        | TSType::TSInferType(_)
        | TSType::TSIntersectionType(_)
        | TSType::TSLiteralType(_)
        | TSType::TSMappedType(_)
        | TSType::TSNamedTupleMember(_)
        | TSType::TSTemplateLiteralType(_)
        | TSType::TSThisType(_)
        | TSType::TSTupleType(_)
        | TSType::TSTypeOperatorType(_)
        | TSType::TSTypePredicate(_)
        | TSType::TSTypeQuery(_)
        | TSType::TSTypeReference(_)
        | TSType::TSUnionType(_)
        | TSType::JSDocNullableType(_)
        | TSType::JSDocNonNullableType(_)
        | TSType::JSDocUnknownType(_) => Member::Unread,
    }
}

/// What calling `expr`, a member read from a namespace asserted to `ty`, is.
fn member_evidence<'a, 'b>(ty: &'b TSType<'a>, name: &str, expr: &Expression<'_>) -> Evidence<'b, 'a> {
    match member(ty, name) {
        Member::Property(ty) => asserted(ty, expr),
        Member::Methods(literal) => results(literal.members.iter().filter_map(|signature| match signature {
            TSSignature::TSMethodSignature(method)
                if method.kind == TSMethodSignatureKind::Method && names_key(&method.key, name) =>
            {
                Some(method.return_type.as_ref().map(|annotation| &annotation.type_annotation))
            }
            TSSignature::TSMethodSignature(_)
            | TSSignature::TSPropertySignature(_)
            | TSSignature::TSIndexSignature(_)
            | TSSignature::TSCallSignatureDeclaration(_)
            | TSSignature::TSConstructSignatureDeclaration(_) => None,
        })),
        Member::Unread => Evidence::Unknown,
    }
}

/// What asserting `ty` on `beneath` says about calling it. One exhaustive match: a new type kind in an OXC release
/// has to be placed here before it compiles.
fn asserted<'a, 'b>(ty: &'b TSType<'a>, beneath: &Expression<'_>) -> Evidence<'b, 'a> {
    match ty {
        TSType::TSAnyKeyword(_) | TSType::TSUnknownKeyword(_) => Evidence::Identity,
        TSType::TSParenthesizedType(inner) => asserted(&inner.type_annotation, beneath),
        TSType::TSTypeQuery(query) if query.type_arguments.is_none() && query_names(&query.expr_name, beneath) => {
            Evidence::Identity
        }
        TSType::TSTypeReference(reference) => Evidence::Reference(reference),
        TSType::TSFunctionType(function) => results(std::iter::once(Some(&function.return_type.type_annotation))),
        TSType::TSTypeLiteral(literal) => results(literal.members.iter().filter_map(|signature| match signature {
            TSSignature::TSCallSignatureDeclaration(call) => {
                Some(call.return_type.as_ref().map(|annotation| &annotation.type_annotation))
            }
            TSSignature::TSPropertySignature(_)
            | TSSignature::TSMethodSignature(_)
            | TSSignature::TSIndexSignature(_)
            | TSSignature::TSConstructSignatureDeclaration(_) => None,
        })),
        TSType::TSTypeQuery(_)
        | TSType::TSBigIntKeyword(_)
        | TSType::TSBooleanKeyword(_)
        | TSType::TSIntrinsicKeyword(_)
        | TSType::TSNeverKeyword(_)
        | TSType::TSNullKeyword(_)
        | TSType::TSNumberKeyword(_)
        | TSType::TSObjectKeyword(_)
        | TSType::TSStringKeyword(_)
        | TSType::TSSymbolKeyword(_)
        | TSType::TSUndefinedKeyword(_)
        | TSType::TSVoidKeyword(_)
        | TSType::TSArrayType(_)
        | TSType::TSConditionalType(_)
        | TSType::TSConstructorType(_)
        | TSType::TSImportType(_)
        | TSType::TSIndexedAccessType(_)
        | TSType::TSInferType(_)
        | TSType::TSIntersectionType(_)
        | TSType::TSLiteralType(_)
        | TSType::TSMappedType(_)
        | TSType::TSNamedTupleMember(_)
        | TSType::TSTemplateLiteralType(_)
        | TSType::TSThisType(_)
        | TSType::TSTupleType(_)
        | TSType::TSTypeOperatorType(_)
        | TSType::TSTypePredicate(_)
        | TSType::TSUnionType(_)
        | TSType::JSDocNullableType(_)
        | TSType::JSDocNonNullableType(_)
        | TSType::JSDocUnknownType(_) => Evidence::Unknown,
    }
}

/// The evidence of a type's call signatures, given their declared results (`None` when one declares none): no
/// component only when there is at least one and each result is [`Returns::NotRenderable`].
fn results<'a, 'b>(signatures: impl Iterator<Item = Option<&'b TSType<'a>>>) -> Evidence<'b, 'a> {
    let mut any = false;
    for result in signatures {
        any = true;
        if !result.is_some_and(|result| matches!(result_of(result), Returns::NotRenderable)) {
            return Evidence::Unknown;
        }
    }
    if any { Evidence::NotRenderable } else { Evidence::Unknown }
}

/// What a call's declared result says about whether it renders or is a component.
#[derive(Clone, Copy)]
enum Returns {
    /// No component or element has this type: a primitive or `object` keyword, `void`, `never`, a literal or template
    /// literal, a type predicate, an object type with no call or construct signature, an array whose elements cannot
    /// render (`unknown[]`, `string[]`).
    NotRenderable,
    /// `null` or `undefined`: what a component may return, and no evidence alone.
    Empty,
    /// Anything that may be a component or an element, or that the extractor does not read (a reference, `unknown`).
    Maybe,
}

fn result_of(ty: &TSType<'_>) -> Returns {
    match ty {
        TSType::TSBigIntKeyword(_)
        | TSType::TSBooleanKeyword(_)
        | TSType::TSNeverKeyword(_)
        | TSType::TSNumberKeyword(_)
        | TSType::TSObjectKeyword(_)
        | TSType::TSStringKeyword(_)
        | TSType::TSSymbolKeyword(_)
        | TSType::TSVoidKeyword(_)
        | TSType::TSLiteralType(_)
        | TSType::TSTemplateLiteralType(_)
        | TSType::TSTypePredicate(_) => Returns::NotRenderable,
        TSType::TSNullKeyword(_) | TSType::TSUndefinedKeyword(_) => Returns::Empty,
        TSType::TSParenthesizedType(inner) => result_of(&inner.type_annotation),
        TSType::TSTypeLiteral(literal) => {
            let callable = literal.members.iter().any(|signature| match signature {
                TSSignature::TSCallSignatureDeclaration(_) | TSSignature::TSConstructSignatureDeclaration(_) => true,
                TSSignature::TSPropertySignature(_)
                | TSSignature::TSMethodSignature(_)
                | TSSignature::TSIndexSignature(_) => false,
            });
            if callable { Returns::Maybe } else { Returns::NotRenderable }
        }
        // `ReactNode[]` renders; `unknown[]` does not, as TypeScript does not take `unknown` for a node.
        TSType::TSArrayType(array) => match (&array.element_type, result_of(&array.element_type)) {
            (TSType::TSAnyKeyword(_) | TSType::TSUnknownKeyword(_), _) => Returns::NotRenderable,
            (_, Returns::Maybe) => Returns::Maybe,
            (_, Returns::NotRenderable | Returns::Empty) => Returns::NotRenderable,
        },
        TSType::TSUnionType(union) => {
            let mut result = Returns::Empty;
            for member in &union.types {
                result = match (result, result_of(member)) {
                    (Returns::Maybe, _) | (_, Returns::Maybe) => return Returns::Maybe,
                    (Returns::NotRenderable, _) | (_, Returns::NotRenderable) => Returns::NotRenderable,
                    (Returns::Empty, Returns::Empty) => Returns::Empty,
                };
            }
            result
        }
        TSType::TSAnyKeyword(_)
        | TSType::TSUnknownKeyword(_)
        | TSType::TSIntrinsicKeyword(_)
        | TSType::TSThisType(_)
        | TSType::TSConditionalType(_)
        | TSType::TSConstructorType(_)
        | TSType::TSFunctionType(_)
        | TSType::TSImportType(_)
        | TSType::TSIndexedAccessType(_)
        | TSType::TSInferType(_)
        | TSType::TSIntersectionType(_)
        | TSType::TSMappedType(_)
        | TSType::TSNamedTupleMember(_)
        | TSType::TSTupleType(_)
        | TSType::TSTypeOperatorType(_)
        | TSType::TSTypeQuery(_)
        | TSType::TSTypeReference(_)
        | TSType::JSDocNullableType(_)
        | TSType::JSDocNonNullableType(_)
        | TSType::JSDocUnknownType(_) => Returns::Maybe,
    }
}

/// Whether `typeof name` is the type of `expr`: the same identifier or the same chain of static members, read through
/// the namespaces' wrappers (the outermost assertion states the type whatever the namespace was asserted to).
fn query_names(name: &TSTypeQueryExprName<'_>, expr: &Expression<'_>) -> bool {
    match name {
        TSTypeQueryExprName::IdentifierReference(id) => matches!(expr, Expression::Identifier(e) if e.name == id.name),
        TSTypeQueryExprName::QualifiedName(qualified) => type_name_names(&qualified.left, &qualified.right, expr),
        TSTypeQueryExprName::ThisExpression(_) => matches!(expr, Expression::ThisExpression(_)),
        TSTypeQueryExprName::TSImportType(_) => false,
    }
}

fn type_name_names(left: &TSTypeName<'_>, right: &IdentifierName<'_>, expr: &Expression<'_>) -> bool {
    let Expression::StaticMemberExpression(member) = expr else { return false };
    if member.property.name != right.name {
        return false;
    }
    let object = peel_expr(&member.object);
    match left {
        TSTypeName::IdentifierReference(id) => matches!(object, Expression::Identifier(e) if e.name == id.name),
        TSTypeName::QualifiedName(qualified) => type_name_names(&qualified.left, &qualified.right, object),
        TSTypeName::ThisExpression(_) => matches!(object, Expression::ThisExpression(_)),
    }
}

/// Whether a dotted chain (`createButton`, `React.forwardRef`) names `expr`, read through the namespaces' wrappers.
fn chain_names(chain: &str, expr: &Expression<'_>) -> bool {
    match (chain.rsplit_once('.'), expr) {
        (None, Expression::Identifier(id)) => id.name == chain,
        (Some((left, right)), Expression::StaticMemberExpression(member)) => {
            member.property.name == right && chain_names(left, peel_expr(&member.object))
        }
        (None | Some(_), _) => false,
    }
}

/// The module-level aliases of a value's type, `type Factory = typeof createButton`, as alias name to the dotted chain
/// it queries. A name declared twice is left out: which one a use means is not read here.
pub(super) fn typeof_aliases(program: &Program<'_>) -> FxHashMap<CompactString, CompactString> {
    fn chain(name: &TSTypeName<'_>) -> Option<String> {
        match name {
            TSTypeName::IdentifierReference(id) => Some(id.name.as_str().to_owned()),
            TSTypeName::QualifiedName(qualified) => {
                Some(format!("{}.{}", chain(&qualified.left)?, qualified.right.name))
            }
            TSTypeName::ThisExpression(_) => None,
        }
    }
    let mut aliases: FxHashMap<CompactString, Option<CompactString>> = FxHashMap::default();
    for statement in &program.body {
        let declaration = match statement {
            Statement::ExportDeclaration(export) => Some(&export.declaration),
            _ => statement.as_declaration(),
        };
        let Some(Declaration::TSTypeAliasDeclaration(declaration)) = declaration else { continue };
        let mut ty = &declaration.type_annotation;
        while let TSType::TSParenthesizedType(inner) = ty {
            ty = &inner.type_annotation;
        }
        let queried = match ty {
            TSType::TSTypeQuery(query) if declaration.type_parameters.is_none() && query.type_arguments.is_none() => {
                match &query.expr_name {
                    TSTypeQueryExprName::IdentifierReference(id) => Some(id.name.as_str().to_owned()),
                    TSTypeQueryExprName::QualifiedName(qualified) => {
                        chain(&qualified.left).map(|left| format!("{left}.{}", qualified.right.name))
                    }
                    TSTypeQueryExprName::ThisExpression(_) | TSTypeQueryExprName::TSImportType(_) => None,
                }
            }
            _ => None,
        };
        aliases
            .entry(CompactString::from(declaration.id.name.as_str()))
            .and_modify(|seen| *seen = None)
            .or_insert_with(|| queried.map(CompactString::from));
    }
    aliases.into_iter().filter_map(|(name, chain)| Some((name, chain?))).collect()
}

/// Counts the wrapper layers `peel` reads, so a test can show that a chain of assertions is read in one pass.
#[cfg(test)]
pub(super) mod steps {
    use std::cell::Cell;

    thread_local!(static STEPS: Cell<u64> = const { Cell::new(0) });

    pub(in crate::extractor) fn count() {
        STEPS.with(|steps| steps.set(steps.get() + 1));
    }

    pub(in crate::extractor) fn take() -> u64 {
        STEPS.with(|steps| steps.replace(0))
    }
}

/// A value read for its name (a callee, the namespace a member is read from), when that name still describes it: see
/// [`Peeled::named`]. `(forwardRef as typeof forwardRef)(…)` and `(React as any).memo` keep it.
pub(super) fn named<'a, 'b>(expr: &'b Expression<'a>) -> Option<&'b Expression<'a>> {
    peel(expr).named()
}

/// What a call invokes, when its name still describes the call: `(forwardRef as F)(…)` and `(forwardRef<R, P>)(…)`
/// call `forwardRef`; `(Object as (v: object) => object)(…)` calls nothing by a name. See [`Peeled::named`].
pub(super) fn callee_of<'a, 'b>(call: &'b CallExpression<'a>) -> Option<&'b Expression<'a>> {
    peel(&call.callee).named()
}

/// The type arguments a call is made with: its own, or those of the instantiation it calls (`(forwardRef<R, P>)(…)`).
pub(super) fn call_type_arguments<'a, 'b>(
    call: &'b CallExpression<'a>,
) -> Option<&'b TSTypeParameterInstantiation<'a>> {
    call.type_arguments.as_deref().or_else(|| peel(&call.callee).type_arguments)
}

