613	/// PascalCase a file's stem for naming an anonymous default-exported
614	/// component that has no identifier of its own — e.g. `button-group.tsx` →
615	/// `ButtonGroup`, `useButton.tsx` → `UseButton`. Splits on any non-alphanumeric
616	/// separator (`-`, `_`, `.`, space) and capitalizes each segment's first
617	/// character. Returns `None` when the path has no usable stem at all (e.g.
618	/// nothing but separators).
619	pub(super) fn pascal_case_from_file_stem(file_path: &Utf8Path) -> Option<String> {
620	    let stem = file_path.file_stem()?;
621	    let mut pascal = String::new();
622	    for segment in stem.split(|c: char| !c.is_alphanumeric()) {
623	        let mut chars = segment.chars();
624	        if let Some(first) = chars.next() {
625	            pascal.extend(first.to_uppercase());
626	            pascal.push_str(chars.as_str());
627	        }
628	    }
629	    (!pascal.is_empty()).then_some(pascal)
630	}
