770	                continue;
771	            }
772	            let (object, property) = member.unwrap_or((callee, callee));
773	            let fill = |text: &str| text.replace("{b}", callee).replace("{o}", object).replace("{m}", property);
774	            let source = format!("{DIFFERENTIAL_HEADER}{}\n{}", fill(prelude), template.replace("{C}", &fill(wrapped)));
